import { FusionObservabilityPanel } from "@/components/FusionObservabilityPanel";
import { useAuth } from "@/_core/hooks/useAuth";
import { startLogin } from "@/const";
import { trpc } from "@/lib/trpc";
import { calculateProbe, calculateStabilityScore, escapeCsvValue, estimateTimeSync, evaluateOffsetAlert, median, type SyncEstimate, type TimeProbe, validateRoomCode } from "@shared/timeMath";
import { filterIanaTimezones, formatCorrectedZoneTime, getAvailableIanaTimezones, getTimezoneWindow, TIMEZONE_PICKER_ROW_HEIGHT } from "@shared/timeZones";
import { buildInsightCsvRows, buildPeerComparisonPoint, getTopComparisonSetups } from "@shared/peerComparison";
import { reconcileSeriesVisibility } from "@shared/chartVisibility";
