type Peer = { id: string; offsetMs: number; uncertaintyMs: number; jitterMs: number; sampleCount: number; updatedAt: number; tags: string[]; description: string | null };
type SourceReading = { id: string; name: string; host: string; tier: "authority" | "regional_pool" | "custom"; region?: string; status: "reachable" | "unreachable" | "blocked"; offsetMs: number | null; delayMs: number | null; uncertaintyMs: number | null; sampledAt: number; detail?: string };
type AnalyticsRange = "24h" | "7d" | "30d";
type FusionRange = "6h" | "24h" | "7d";

const BURST_SIZE = 10;
const DEFAULT_ZONES = ["UTC", "America/Los_Angeles", "America/New_York", "Europe/London", "Europe/Berlin", "Asia/Kolkata", "Asia/Tokyo", "Australia/Sydney"];

function formatNumber(value: number, digits = 3) { return Number.isFinite(value) ? value.toFixed(digits) : "—"; }
function formatOffset(value: number | null | undefined) { return value === null || value === undefined || !Number.isFinite(value) ? "unavailable" : `${value >= 0 ? "+" : ""}${formatNumber(value)} ms`; }
function formatUncertainty(value: number | null | undefined) { return value === null || value === undefined || !Number.isFinite(value) ? "± unavailable" : `± ${formatNumber(Math.abs(value))} ms`; }
function confidenceTone(confidence: "high" | "medium" | "low") { return confidence === "high" ? "text-[#a3e635] bg-[#a3e635]/10 border-[#a3e635]/35" : confidence === "medium" ? "text-amber-300 bg-amber-300/10 border-amber-300/35" : "text-red-300 bg-red-400/10 border-red-400/35"; }
function deriveConfidence(uncertaintyMs: number, samples: number): "high" | "medium" | "low" { return uncertaintyMs <= 3 && samples >= 3 ? "high" : uncertaintyMs <= 15 && samples >= 3 ? "medium" : "low"; }
function createId(prefix: string) { return `${prefix}-${crypto.randomUUID().replaceAll("-", "").slice(0, 20)}`; }
function renderPreciseUtc(epochMs: number) { const whole = Math.floor(epochMs); const date = new Date(whole); const base = date.toISOString().replace("T", " ").replace("Z", ""); const micros = Math.floor(Math.max(0, epochMs - whole) * 1000).toString().padStart(3, "0"); return `${base}${micros} UTC`; }
function zoneLabel(zone: string) { return zone.replaceAll("_", " ").replaceAll("/", " / "); }
function SectionLabel({ icon: Icon, children }: { icon: typeof Clock3; children: string }) { return <div className="flex items-center gap-2 text-[10px] font-bold tracking-[.2em] text-[#a3e635]"><Icon className="h-3.5 w-3.5" />{children}</div>; }

export default function Home() {
  const [sessionId] = useState(() => createId("session"));
  const [estimate, setEstimate] = useState<SyncEstimate | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [clockEpoch, setClockEpoch] = useState(() => performance.timeOrigin + performance.now());
  const [timerResolutionUs, setTimerResolutionUs] = useState<number | null>(null);
  const [roomInput, setRoomInput] = useState("MESH1");
  const [activeRoom, setActiveRoom] = useState<string | null>(null);
  const [peerId, setPeerId] = useState<string | null>(null);
  const [peerStatus, setPeerStatus] = useState<"offline" | "connecting" | "connected">("offline");
  const [peers, setPeers] = useState<Peer[]>([]);
  const [shareHardwareContext, setShareHardwareContext] = useState(false);
  const [hardwareTags, setHardwareTags] = useState("");
  const [hardwareDescription, setHardwareDescription] = useState("");
  const [alertEnabled, setAlertEnabled] = useState(() => localStorage.getItem("chronomesh-alert-enabled") !== "false");
  const [alertThresholdText, setAlertThresholdText] = useState(() => localStorage.getItem("chronomesh-alert-threshold") ?? "25");
  const [timezoneSearch, setTimezoneSearch] = useState("");
  const [worldZones, setWorldZones] = useState<string[]>(DEFAULT_ZONES);
  const [timezonePickerScrollTop, setTimezonePickerScrollTop] = useState(0);
  const [customHost, setCustomHost] = useState("");
  const [customResult, setCustomResult] = useState<SourceReading | null>(null);
  const [saveHardwareTemplate, setSaveHardwareTemplate] = useState(false);
  const [analyticsRange, setAnalyticsRange] = useState<AnalyticsRange>("24h");
  const [fusionRange, setFusionRange] = useState<FusionRange>("24h");
  const [publicLeaderboardOptIn, setPublicLeaderboardOptIn] = useState(false);
  const [publicSetupLabel, setPublicSetupLabel] = useState("");
  const [highContrastMode, setHighContrastMode] = useState(() => localStorage.getItem("chronomesh-high-contrast") === "true");
  const [communityHost, setCommunityHost] = useState("");
  const [communityName, setCommunityName] = useState("");
  const [communityRegion, setCommunityRegion] = useState("");
  const [communityPublic, setCommunityPublic] = useState(false);
  const [communityVerificationToken, setCommunityVerificationToken] = useState<string | null>(null);
  const profileHydrated = useRef(false);
  const socketRef = useRef<WebSocket | null>(null);
  const estimateRef = useRef<SyncEstimate | null>(null);
  const alertRef = useRef<"safe" | "indeterminate" | "alert">("safe");
  const recordBurst = trpc.chronomesh.recordBurst.useMutation();
  const health = trpc.chronomesh.upstreamHealth.useQuery(undefined, { staleTime: 12_000, refetchInterval: 15_000, retry: 1 });
  const sourceHealth = trpc.chronomesh.sourceHealth.useQuery(undefined, { staleTime: 12_000, refetchInterval: 15_000, retry: 1 });
  const history = trpc.chronomesh.measurementHistory.useQuery({ sessionId, limit: 2_000 }, { enabled: false, retry: 1 });
  const customProbe = trpc.chronomesh.probeCustomSource.useMutation({ onSuccess: reading => setCustomResult(reading) });
  const diagnostics = trpc.chronomesh.realtimeDiagnostics.useQuery(undefined, { staleTime: 15_000, refetchInterval: 15_000 });
  const analytics = trpc.chronomesh.sourceAnalytics.useQuery({ range: analyticsRange }, { staleTime: 30_000, retry: 1 });
  const sourceInsight = trpc.chronomesh.sourceHistoryInsight.useQuery({ range: analyticsRange }, { staleTime: 5 * 60_000, retry: 1 });
  const { isAuthenticated, user } = useAuth();
  const globalMesh = trpc.chronomesh.globalMesh.useQuery(undefined, { staleTime: 35_000, refetchInterval: 45_000, retry: 1 });
  const fusionObservability = trpc.chronomesh.fusionObservability.useQuery({ range: fusionRange }, { staleTime: 25_000, refetchInterval: 45_000, retry: 1 });
  const publicSourceReviewQueue = trpc.chronomesh.publicSourceReviewQueue.useQuery(undefined, { staleTime: 20_000, refetchInterval: 45_000, retry: 1 });
  const myCommunitySources = trpc.chronomesh.myCommunitySources.useQuery(undefined, { enabled: isAuthenticated, staleTime: 20_000 });
  const registerCommunitySource = trpc.chronomesh.registerCommunitySource.useMutation({ onSuccess: result => { if (result.verificationToken) { setCommunityVerificationToken(result.verificationToken); toast.success("Source saved. Publish the DNS TXT token shown below, then verify."); } setCommunityHost(""); setCommunityName(""); setCommunityRegion(""); void myCommunitySources.refetch(); }, onError: error => toast.error(error.message) });
  const verifyCommunitySource = trpc.chronomesh.verifyCommunitySource.useMutation({ onSuccess: result => { toast[result.activated ? "success" : "error"](result.activated ? "Community time source is verified and active." : "Source could not be activated."); void myCommunitySources.refetch(); void globalMesh.refetch(); }, onError: error => toast.error(error.message) });
  const setCommunitySourceState = trpc.chronomesh.setCommunitySourceState.useMutation({ onSuccess: () => { void myCommunitySources.refetch(); void globalMesh.refetch(); }, onError: error => toast.error(error.message) });
  const submitSourceReviewApplication = trpc.chronomesh.submitSourceReviewApplication.useMutation({ onSuccess: () => { toast.success("Source application submitted to the review queue."); void publicSourceReviewQueue.refetch(); }, onError: error => toast.error(error.message) });
  const savedProfile = trpc.profile.getChronoPreferences.useQuery(undefined, { enabled: isAuthenticated, staleTime: 60_000 });
  const saveProfile = trpc.profile.saveChronoPreferences.useMutation({ onSuccess: result => { if (result.stored) { setSaveHardwareTemplate(result.preferences.hardwareTemplateOptIn); toast.success("Signed-in ChronoMesh preferences saved."); } else toast.error("Preferences could not be persisted."); } });
  const publishPublicStability = trpc.chronomesh.publishPublicStability.useMutation({ onSuccess: () => toast.success("Your opted-in public setup is now represented on the leaderboard."), onError: error => toast.error(error.message) });

  const authorityOffset = useMemo(() => { const offsets = (health.data?.readings ?? []).flatMap(reading => reading.offsetMs === null ? [] : [reading.offsetMs]); return offsets.length ? median(offsets) : 0; }, [health.data]);
  const authorityUncertainty = useMemo(() => { const values = (health.data?.readings ?? []).flatMap(reading => reading.uncertaintyMs === null ? [] : [reading.uncertaintyMs]); return values.length ? median(values) : 0; }, [health.data]);
  const correctedOffset = (estimate?.offsetMs ?? 0) + authorityOffset;
  const totalUncertainty = (estimate?.uncertaintyMs ?? Infinity) + authorityUncertainty;
  const alertThreshold = Number(alertThresholdText);
  const alertState = alertEnabled && estimate ? evaluateOffsetAlert(estimate.offsetMs, estimate.uncertaintyMs, alertThreshold, alertRef.current === "alert") : "safe";
  const allTimezones = useMemo(getAvailableIanaTimezones, []);
  const filteredTimezones = useMemo(() => filterIanaTimezones(allTimezones, timezoneSearch), [allTimezones, timezoneSearch]);
  const timezoneWindow = useMemo(() => getTimezoneWindow(filteredTimezones, timezonePickerScrollTop, TIMEZONE_PICKER_ROW_HEIGHT * 8), [filteredTimezones, timezonePickerScrollTop]);
  const controlledSources = (sourceHealth.data?.readings ?? []) as SourceReading[];
  const authoritySources = controlledSources.filter(source => source.tier === "authority");
  const regionalSources = controlledSources.filter(source => source.tier === "regional_pool");
  const analyticsTimeline = (analytics.data?.timeline ?? []).map(point => ({ ...point, time: new Date(point.timestamp).toLocaleString([], { month: "short", day: "numeric", hour: analyticsRange === "30d" ? undefined : "2-digit" }) }));

  const sendCurrentReport = useCallback((nextEstimate: SyncEstimate | null = estimateRef.current) => {
    const socket = socketRef.current;
    if (!nextEstimate || socket?.readyState !== WebSocket.OPEN) return;
    socket.send(JSON.stringify({ type: "report", offsetMs: nextEstimate.offsetMs, uncertaintyMs: nextEstimate.uncertaintyMs, jitterMs: nextEstimate.jitterMs, sampleCount: nextEstimate.samples.length }));
  }, []);
  const sendHardwareProfile = useCallback(() => {
    const socket = socketRef.current;
    if (socket?.readyState !== WebSocket.OPEN) return;
    const tags = shareHardwareContext ? hardwareTags.split(",").map(tag => tag.trim()).filter(Boolean).slice(0, 5) : [];
    socket.send(JSON.stringify({ type: "profile", shareHardwareContext, tags, description: shareHardwareContext ? hardwareDescription : null }));
  }, [hardwareDescription, hardwareTags, shareHardwareContext]);

  const runSync = useCallback(async () => {
    if (isSyncing) return; setIsSyncing(true); const probes: TimeProbe[] = [];
    try {
      for (let sampleIndex = 1; sampleIndex <= BURST_SIZE; sampleIndex += 1) {
        const t1 = Date.now(); const response = await fetch("/api/timesync", { cache: "no-store", headers: { "x-chronomesh-probe": "burst" } }); const t4 = Date.now();
        if (!response.ok) throw new Error("The ChronoMesh time edge did not respond.");
        const data = await response.json() as { serverReceiveMs: number; serverSendMs: number };
        probes.push(calculateProbe(sampleIndex, t1, data.serverReceiveMs, data.serverSendMs, t4));
      }
      const nextEstimate = estimateTimeSync(probes); setEstimate(nextEstimate); estimateRef.current = nextEstimate; sendCurrentReport(nextEstimate);
      recordBurst.mutate({ sessionId, burstId: createId("burst"), roomCode: activeRoom, samples: probes.map(({ sampleIndex, t1, t2, t3, t4 }) => ({ sampleIndex, t1, t2, t3, t4 })) });
      toast.success(`Burst synchronized: ${formatOffset(nextEstimate.offsetMs)} ${formatUncertainty(nextEstimate.uncertaintyMs)}`);
    } catch (error) { toast.error(error instanceof Error ? error.message : "Synchronization did not complete."); } finally { setIsSyncing(false); }
  }, [activeRoom, isSyncing, recordBurst, sendCurrentReport, sessionId]);

  const joinRoom = useCallback(() => {
    const roomCode = roomInput.trim().toUpperCase();
    if (!validateRoomCode(roomCode)) { toast.error("Use an exactly five-character room code (A–Z, 0–9)."); return; }
    socketRef.current?.close(); setPeerStatus("connecting"); setPeers([]);
    const protocol = window.location.protocol === "https:" ? "wss" : "ws"; const socket = new WebSocket(`${protocol}://${window.location.host}/ws/room`); socketRef.current = socket;
    socket.onopen = () => socket.send(JSON.stringify({ type: "join", roomCode }));
    socket.onmessage = event => {
      const message = JSON.parse(String(event.data)) as { type: string; roomCode?: string; peerId?: string; peers?: Peer[]; message?: string };
      if (message.type === "identity" && message.peerId) setPeerId(message.peerId);
      if (message.type === "joined" && message.roomCode) { setActiveRoom(message.roomCode); setPeerStatus("connected"); toast.success(`Joined anonymous mesh room ${message.roomCode}.`); sendCurrentReport(); sendHardwareProfile(); }
      if (message.type === "roomState" && message.peers) setPeers(message.peers);
      if (message.type === "error") toast.error(message.message ?? "Room transport error.");
    };
    socket.onerror = () => toast.error("The peer transport could not connect.");
    socket.onclose = () => { if (socketRef.current === socket) setPeerStatus("offline"); };
  }, [roomInput, sendCurrentReport, sendHardwareProfile]);

  const addWorldZone = (zone: string) => { setWorldZones(current => current.includes(zone) ? current : [...current, zone]); setTimezoneSearch(""); setTimezonePickerScrollTop(0); };
  const removeWorldZone = (zone: string) => setWorldZones(current => current.filter(item => item !== zone));
  const exportCsv = async () => {
    const query = await history.refetch(); const stored = query.data ?? [];
    const capturedUtc = new Date().toISOString();
    const insightRows = buildInsightCsvRows(sourceInsight.data, capturedUtc).map(row => [row[0], row[1], sessionId, "source_history", "", "", "", "", "", "", "", "", "", "", "", row[2], row[3], row[4], row[5]]);
    const rows = [
      ["record_type", "captured_utc", "session_id", "burst_id", "sample_index", "offset_ms", "delay_ms", "rtt_ms", "jitter_ms", "uncertainty_ms", "t1_ms", "t2_ms", "t3_ms", "t4_ms", "room_code", "insight_range", "insight_model", "insight_field", "insight_value"],
      ...(estimate?.samples ?? []).map(sample => ["live_probe", capturedUtc, sessionId, "current", sample.sampleIndex, sample.offsetMs, sample.delayMs, sample.rttMs, estimate?.jitterMs ?? "", estimate?.uncertaintyMs ?? "", sample.t1, sample.t2, sample.t3, sample.t4, activeRoom ?? "", "", "", "", ""]),
      ...stored.map(sample => ["persisted_probe", sample.createdAt.toISOString(), sample.sessionId, sample.burstId, sample.sampleIndex, sample.offsetMs, sample.delayMs, sample.clientReceivedMs - sample.clientSentMs, sample.jitterMs, sample.uncertaintyMs, sample.clientSentMs, sample.serverReceivedMs, sample.serverSentMs, sample.clientReceivedMs, sample.roomCode ?? "", "", "", "", ""]),
      ...(estimate ? [["jitter_trace", capturedUtc, sessionId, "current", "", "", "", "", estimate.jitterMs, estimate.uncertaintyMs, "", "", "", "", activeRoom ?? "", "", "", "", ""]] : []),
      ...insightRows,
    ];
    const csv = rows.map(row => row.map(escapeCsvValue).join(",")).join("\r\n"); const blob = new Blob([csv], { type: "text/csv;charset=utf-8" }); const href = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = href; anchor.download = `chronomesh-sync-${new Date().toISOString().replace(/[:.]/g, "-")}.csv`; anchor.click(); URL.revokeObjectURL(href);
    toast.success(`CSV exported with ${Math.max(0, rows.length - 1)} records${insightRows.length ? " including AI source insight" : ""}.`);
  };
  const persistProfile = () => {
    if (!isAuthenticated) { startLogin(); return; }
    const threshold = Number(alertThresholdText);
    if (!Number.isFinite(threshold) || threshold <= 0) { toast.error("Set a positive alert threshold before saving."); return; }
    saveProfile.mutate({ alertEnabled, alertThresholdMs: threshold, hardwareTemplateOptIn: saveHardwareTemplate, hardwareTags: saveHardwareTemplate ? hardwareTags.split(",").map(tag => tag.trim()).filter(Boolean).slice(0, 5) : [], hardwareDescription: saveHardwareTemplate ? hardwareDescription || null : null, worldZones: worldZones.slice(0, 24), publicLeaderboardOptIn, publicSetupLabel: publicLeaderboardOptIn ? publicSetupLabel || null : null, highContrastMode });
  };
  const publishCurrentStability = () => {
    if (!isAuthenticated) { startLogin(); return; }
    if (!estimate) { toast.error("Run a synchronization burst before publishing a stability summary."); return; }
    if (!publicLeaderboardOptIn || !publicSetupLabel.trim()) { toast.error("Enable public sharing and save an anonymous setup label first."); return; }
    publishPublicStability.mutate({ offsetMs: estimate.offsetMs, jitterMs: estimate.jitterMs, uncertaintyMs: estimate.uncertaintyMs, sampleCount: estimate.samples.length });
  };

  useEffect(() => { const frame = () => { setClockEpoch(performance.timeOrigin + performance.now() + correctedOffset); requestAnimationFrame(frame); }; const id = requestAnimationFrame(frame); return () => cancelAnimationFrame(id); }, [correctedOffset]);
  useEffect(() => { let smallest = Infinity; let previous = performance.now(); for (let i = 0; i < 2_000; i += 1) { const current = performance.now(); const difference = current - previous; if (difference > 0 && difference < smallest) smallest = difference; previous = current; } setTimerResolutionUs(Number.isFinite(smallest) ? smallest * 1000 : null); void runSync(); return () => socketRef.current?.close(); }, []);
  useEffect(() => { if (peerStatus !== "connected" || !estimate) return; sendCurrentReport(estimate); const intervalId = window.setInterval(() => sendCurrentReport(), 5_000); return () => window.clearInterval(intervalId); }, [estimate, peerStatus, sendCurrentReport]);
  useEffect(() => { if (peerStatus === "connected") sendHardwareProfile(); }, [hardwareDescription, hardwareTags, peerStatus, sendHardwareProfile, shareHardwareContext]);
  useEffect(() => { localStorage.setItem("chronomesh-alert-enabled", String(alertEnabled)); localStorage.setItem("chronomesh-alert-threshold", alertThresholdText); }, [alertEnabled, alertThresholdText]);
  useEffect(() => { localStorage.setItem("chronomesh-high-contrast", String(highContrastMode)); }, [highContrastMode]);
  useEffect(() => { if (!savedProfile.data || profileHydrated.current) return; profileHydrated.current = true; setAlertEnabled(savedProfile.data.alertEnabled); setAlertThresholdText(String(savedProfile.data.alertThresholdMs)); setSaveHardwareTemplate(savedProfile.data.hardwareTemplateOptIn); setPublicLeaderboardOptIn(savedProfile.data.publicLeaderboardOptIn); setPublicSetupLabel(savedProfile.data.publicSetupLabel ?? ""); setHighContrastMode(savedProfile.data.highContrastMode); if (savedProfile.data.hardwareTemplateOptIn) { setHardwareTags(savedProfile.data.hardwareTags.join(", ")); setHardwareDescription(savedProfile.data.hardwareDescription ?? ""); } setWorldZones(savedProfile.data.worldZones); }, [savedProfile.data]);
  useEffect(() => {
    if (!activeRoom || !diagnostics.data?.managedPubSub || !diagnostics.data.pusherKey || !diagnostics.data.pusherCluster) return;
    const pusher = new PusherClient(diagnostics.data.pusherKey, { cluster: diagnostics.data.pusherCluster, forceTLS: true }); const channel = pusher.subscribe(`chronomesh-room-${activeRoom}`);
    const applyManagedRelay = (event: { eventType?: "upsert" | "remove"; peerId?: string; payload?: Peer | null }) => { const remotePeerId = event.peerId; if (!remotePeerId || remotePeerId === peerId) return; setPeers(current => { const next = new Map(current.map(item => [item.id, item])); if (event.eventType === "remove") next.delete(remotePeerId); else if (event.eventType === "upsert" && event.payload?.id === remotePeerId) next.set(remotePeerId, event.payload); return Array.from(next.values()); }); };
    channel.bind("chronomesh-relay", applyManagedRelay); return () => { channel.unbind("chronomesh-relay", applyManagedRelay); pusher.unsubscribe(`chronomesh-room-${activeRoom}`); pusher.disconnect(); };
  }, [activeRoom, diagnostics.data?.managedPubSub, diagnostics.data?.pusherCluster, diagnostics.data?.pusherKey, peerId]);
  useEffect(() => { if (alertState === "alert" && alertRef.current !== "alert") toast.error(`Offset alert: conservative lower bound exceeded ${alertThresholdText} ms.`); if (alertState === "indeterminate" && alertRef.current === "safe") toast.warning("Offset threshold lies inside the current uncertainty envelope."); alertRef.current = alertState; }, [alertState, alertThresholdText]);

  const ownPeer = peerId ? peers.find(peer => peer.id === peerId) : undefined;
  const rankedPeers = [...peers].sort((a, b) => Math.abs(a.offsetMs) - Math.abs(b.offsetMs));
  const lastSample = estimate?.samples.at(-1);
  const chartData = (estimate?.samples ?? []).map(sample => ({ sample: `#${sample.sampleIndex}`, offset: Number(sample.offsetMs.toFixed(3)), delay: Number(sample.delayMs.toFixed(3)) }));
  const heroTone = alertState === "alert" ? "border-red-400/60 from-[#291211] via-[#16100f]" : alertState === "indeterminate" ? "border-amber-300/55 from-[#261f0f] via-[#15140f]" : "neon-border from-[#151b0f] via-[#101110]";


  return <div className={`min-h-screen bg-[#090a0a] text-[#e4e4e7] cyber-grid selection:bg-[#a3e635] selection:text-black ${highContrastMode ? "chronomesh-high-contrast" : ""}`}>
    <header className="sticky top-0 z-20 border-b border-[#a3e635]/15 bg-[#090a0a]/90 backdrop-blur-xl"><div className="mx-auto flex max-w-[1600px] items-center justify-between gap-4 px-5 py-3 lg:px-8"><div className="flex items-center gap-3"><div className="grid h-8 w-8 place-items-center border border-[#a3e635]/50 bg-[#a3e635]/10"><Network className="h-4 w-4 text-[#a3e635]" /></div><div><div className="text-sm font-bold tracking-[.17em] text-[#f4f4f5]">CHRONOMESH</div><div className="numeric text-[9px] tracking-[.18em] text-[#71717a]">PRECISION CLOCK MESH / V0.3</div></div></div><div className="hidden items-center gap-5 text-[10px] tracking-[.15em] text-[#a1a1aa] md:flex"><span>UTC DISCIPLINE</span><span>ANONYMOUS PEERS</span><span>TIME-SOURCE FIELDWORK</span></div><div className="flex items-center gap-2"><Link href="/leaderboard" className="numeric border border-[#a3e635]/30 px-2.5 py-1.5 text-[10px] text-[#a3e635] hover:bg-[#a3e635]/10"><Trophy className="mr-1 inline h-3 w-3" />PUBLIC RANKS</Link><button type="button" onClick={() => setHighContrastMode(value => !value)} aria-pressed={highContrastMode} className={`numeric border px-2.5 py-1.5 text-[10px] ${highContrastMode ? "border-white bg-white text-black" : "border-[#a3e635]/30 text-[#a3e635]"}`}><Contrast className="mr-1 inline h-3 w-3" />{highContrastMode ? "HIGH CONTRAST" : "READABLE"}</button><div className="flex items-center gap-2 border border-[#a3e635]/20 bg-[#a3e635]/5 px-2.5 py-1.5 text-[10px] font-semibold tracking-wider text-[#a3e635]"><span className="live-dot h-1.5 w-1.5 rounded-full bg-[#a3e635] shadow-[0_0_9px_#a3e635]" />TIME EDGE ONLINE</div></div></div></header>
    <main className="mx-auto max-w-[1600px] px-5 py-6 lg:px-8">
      <FusionObservabilityPanel data={fusionObservability.data} isLoading={fusionObservability.isLoading} range={fusionRange} onRangeChange={setFusionRange} />
      <GlobalSourceMeshPanel mesh={globalMesh.data} isLoading={globalMesh.isLoading} isAuthenticated={isAuthenticated} communitySources={myCommunitySources.data ?? []} publicApplications={publicSourceReviewQueue.data ?? []} host={communityHost} name={communityName} region={communityRegion} isPublic={communityPublic} verificationToken={communityVerificationToken} isRegistering={registerCommunitySource.isPending} isApplying={submitSourceReviewApplication.isPending} onHostChange={setCommunityHost} onNameChange={setCommunityName} onRegionChange={setCommunityRegion} onPublicChange={setCommunityPublic} onRegister={() => registerCommunitySource.mutate({ host: communityHost, displayName: communityName, publicMetadataOptIn: communityPublic, publicLabel: communityPublic ? communityName : null, region: communityRegion.trim() || null })} onVerify={sourceId => verifyCommunitySource.mutate({ sourceId })} onSetState={(sourceId, state) => setCommunitySourceState.mutate({ sourceId, state })} onSubmitApplication={sourceId => submitSourceReviewApplication.mutate({ sourceId, capabilities: ["NTP service", "DNS ownership verified"], publicQueueOptIn: communityPublic, requestedPublicLabel: communityPublic ? communityName.trim() || null : null })} onStartLogin={() => startLogin()} />
      <section className={`scanline relative mb-5 overflow-hidden border bg-gradient-to-br p-5 lg:p-7 ${heroTone}`}><div className="absolute right-0 top-0 h-28 w-1/2 bg-[radial-gradient(ellipse_at_top_right,rgba(163,230,53,.12),transparent_62%)]" /><div className="relative grid gap-6 lg:grid-cols-[1.25fr_.75fr] lg:items-end"><div><SectionLabel icon={alertState === "alert" ? TriangleAlert : Clock3}>{alertState === "alert" ? "OFFSET ALERT / CONSERVATIVE BOUND EXCEEDED" : alertState === "indeterminate" ? "OFFSET WATCH / UNCERTAINTY OVERLAPS THRESHOLD" : "CORRECTED UTC / MESH SOLUTION"}</SectionLabel><div className="numeric mt-3 break-all text-[clamp(1.55rem,4.2vw,4.75rem)] font-medium leading-none tracking-[-.055em] text-[#f4f4f5]">{renderPreciseUtc(clockEpoch)} <span className="whitespace-nowrap text-[.3em] tracking-normal text-[#a3e635]">{formatUncertainty(totalUncertainty)}</span></div><div className="numeric mt-4 flex flex-wrap items-center gap-x-3 gap-y-2 text-xs"><span className="rounded border border-[#a3e635]/40 bg-[#a3e635]/10 px-2 py-1 text-[#a3e635]">UTC estimate {formatUncertainty(totalUncertainty)}</span><span className="text-[#a1a1aa]">client → mesh {formatOffset(estimate?.offsetMs)} {formatUncertainty(estimate?.uncertaintyMs)}</span>{alertState !== "safe" && <span className={alertState === "alert" ? "text-red-300" : "text-amber-300"}>threshold {formatNumber(alertThreshold)} ms / {alertState.toUpperCase()}</span>}</div></div><div className="grid grid-cols-2 gap-2 sm:grid-cols-4 lg:grid-cols-2"><Metric label="MESH OFFSET" value={formatOffset(estimate?.offsetMs)} detail={formatUncertainty(estimate?.uncertaintyMs)} /><Metric label="AUTHORITY OFFSET" value={formatOffset(authorityOffset)} detail={formatUncertainty(authorityUncertainty)} /><Metric label="JITTER" value={estimate ? `${formatNumber(estimate.jitterMs)} ms` : "calibrating"} detail={estimate ? formatUncertainty(estimate.jitterMs) : "± awaiting burst"} /><Metric label="CONFIDENCE" value={(estimate?.confidence ?? "low").toUpperCase()} detail={estimate ? formatUncertainty(estimate.uncertaintyMs) : "± pending"} /></div></div></section>
      <div className="grid gap-5 xl:grid-cols-12">
        <section className="cyber-card p-5 xl:col-span-8"><div className="flex flex-wrap items-start justify-between gap-4"><div><SectionLabel icon={Activity}>SYNC ENGINE / FOUR-TIMESTAMP BURST</SectionLabel><p className="mt-2 max-w-2xl text-sm leading-relaxed text-[#a1a1aa]">Ten HTTPS probes are sorted by network delay. Only the lowest-delay quartile informs the median offset; every result carries its conservative uncertainty envelope.</p></div><div className="flex gap-2"><Button variant="outline" onClick={() => void exportCsv()} className="rounded-none border-[#a3e635]/30 bg-transparent px-3 font-mono text-xs text-[#a3e635] hover:bg-[#a3e635]/10 hover:text-[#a3e635]"><Download className="mr-2 h-3.5 w-3.5" />EXPORT CSV</Button><Button onClick={() => void runSync()} disabled={isSyncing} className="rounded-none bg-[#a3e635] px-4 font-mono text-xs font-bold text-black hover:bg-[#bef264]"><RefreshCw className={`mr-2 h-3.5 w-3.5 ${isSyncing ? "animate-spin" : ""}`} />{isSyncing ? "SYNCING 10/10" : "RUN NEW BURST"}</Button></div></div><div className="mt-5 grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="h-[238px] border border-[#a3e635]/15 bg-black/20 p-3"><div className="mb-2 flex items-center justify-between"><span className="numeric text-[10px] tracking-widest text-[#a1a1aa]">JITTER TRACE / OFFSET DISPERSION</span><span className="numeric text-[10px] text-[#a3e635]">{estimate ? `${estimate.retainedSamples.length}/${estimate.samples.length} RETAINED` : "AWAITING DATA"}</span></div><ResponsiveContainer width="100%" height="88%"><LineChart data={chartData}><CartesianGrid stroke="rgba(163,230,53,.10)" strokeDasharray="2 4" vertical={false} /><XAxis dataKey="sample" tick={{ fill: "#71717a", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "#71717a", fontSize: 10 }} axisLine={false} tickLine={false} width={44} /><Tooltip contentStyle={{ background: "#111210", border: "1px solid rgba(163,230,53,.35)", fontFamily: "monospace", fontSize: 11 }} labelStyle={{ color: "#a3e635" }} /><Line type="monotone" dataKey="offset" name="offset ms" stroke="#a3e635" strokeWidth={2} dot={{ fill: "#a3e635", r: 3 }} activeDot={{ r: 4 }} /></LineChart></ResponsiveContainer></div><FormulaPanel sample={lastSample} timerResolutionUs={timerResolutionUs} /></div><RawSamplesTable samples={estimate?.samples ?? []} retained={new Set(estimate?.retainedSamples.map(sample => sample.sampleIndex) ?? [])} timerResolutionUs={timerResolutionUs} /></section>
        <section className="cyber-card p-5 xl:col-span-4"><div className="flex items-center justify-between gap-3"><SectionLabel icon={BellRing}>OFFSET ALERT / YOUR BOUNDARY</SectionLabel><div className={`numeric border px-2 py-1 text-[9px] ${alertState === "alert" ? "border-red-400/40 text-red-300" : alertState === "indeterminate" ? "border-amber-300/40 text-amber-300" : "border-[#a3e635]/30 text-[#a3e635]"}`}>{alertEnabled ? alertState.toUpperCase() : "DISABLED"}</div></div><p className="mt-2 text-xs leading-relaxed text-[#a1a1aa]">An alert only fires when the measured offset’s conservative lower bound exceeds your threshold. The uncertain band becomes a watch state instead of a false alarm.</p><div className="mt-4 grid grid-cols-[1fr_auto] gap-2"><Input value={alertThresholdText} inputMode="decimal" onChange={event => setAlertThresholdText(event.target.value.replace(/[^0-9.]/g, ""))} aria-label="Offset alert threshold in milliseconds" className="numeric h-9 rounded-none border-[#a3e635]/30 bg-black/25 text-[#f4f4f5]" /><Button onClick={() => setAlertEnabled(value => !value)} className="h-9 rounded-none bg-[#a3e635] px-3 font-mono text-[10px] font-bold text-black hover:bg-[#bef264]">{alertEnabled ? "ARMED" : "ARM"}</Button></div><div className="numeric mt-3 text-[10px] text-[#71717a]">THRESHOLD {Number.isFinite(alertThreshold) && alertThreshold > 0 ? `${formatNumber(alertThreshold)} ms` : "INVALID"} / LOCAL BROWSER PREFERENCE</div><div className="mt-4 border-t border-[#a3e635]/15 pt-3"><SectionLabel icon={Globe2}>SERVER NTP HEALTH / WORLD LAYER</SectionLabel><div className="mt-3 space-y-2">{(health.data?.readings ?? []).map(reading => <AuthorityRow key={reading.id} reading={reading} />)}{health.isError && <div className="flex gap-2 border border-red-400/25 bg-red-400/5 p-3 text-xs text-red-200"><TriangleAlert className="h-4 w-4 shrink-0" />Health data is unavailable; no substitute value is displayed.</div>}</div></div></section>
        <section className="cyber-card p-5 xl:col-span-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><SectionLabel icon={Radio}>LIVE PEER MESH / COMMON REFERENCE</SectionLabel><p className="mt-2 max-w-xl text-xs leading-relaxed text-[#a1a1aa]">Peers expose only an ephemeral ID, current timing estimate, and optional context they choose to share. No peer IP address is released.</p></div><div className={`numeric flex items-center gap-2 border px-2 py-1 text-[10px] ${peerStatus === "connected" ? "border-[#a3e635]/35 text-[#a3e635]" : "border-[#52525b] text-[#a1a1aa]"}`}><Signal className="h-3.5 w-3.5" />{peerStatus.toUpperCase()}</div></div><div className="mt-4 flex flex-wrap gap-2"><Input value={roomInput} maxLength={5} onChange={event => setRoomInput(event.target.value.toUpperCase().replace(/[^A-Z0-9]/g, ""))} aria-label="Five-character room code" className="numeric h-9 w-44 rounded-none border-[#a3e635]/30 bg-black/25 text-center text-sm tracking-[.28em] text-[#f4f4f5] focus-visible:ring-[#a3e635]" /><Button onClick={joinRoom} className="h-9 rounded-none bg-[#a3e635] px-4 font-mono text-xs font-bold text-black hover:bg-[#bef264]"><Network className="mr-2 h-3.5 w-3.5" />JOIN ROOM</Button>{activeRoom && <div className="numeric flex items-center px-2 text-[10px] text-[#a3e635]">ROOM {activeRoom} / YOU {peerId ?? "—"}</div>}</div><div className="mt-4 border border-[#a3e635]/15 bg-black/20 p-3"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="numeric text-[10px] tracking-widest text-[#a3e635]">OPTIONAL HARDWARE CONTEXT</div><p className="mt-1 text-[10px] text-[#71717a]">Tags and description are sent only to the active anonymous room. Disable to clear them from live room state immediately.</p></div><button type="button" onClick={() => setShareHardwareContext(value => !value)} className={`numeric border px-2 py-1 text-[10px] ${shareHardwareContext ? "border-[#a3e635]/40 bg-[#a3e635]/10 text-[#a3e635]" : "border-[#52525b] text-[#a1a1aa]"}`}>{shareHardwareContext ? "SHARING" : "PRIVATE"}</button></div>{shareHardwareContext && <div className="mt-3 grid gap-2 md:grid-cols-2"><Input value={hardwareTags} onChange={event => setHardwareTags(event.target.value)} maxLength={124} placeholder="GPSDO, PPS, Linux / comma-separated" aria-label="Optional hardware tags" className="numeric h-9 rounded-none border-[#a3e635]/30 bg-black/25 text-xs text-[#f4f4f5]" /><Input value={hardwareDescription} onChange={event => setHardwareDescription(event.target.value)} maxLength={160} placeholder="Optional setup description (160 chars)" aria-label="Optional hardware description" className="h-9 rounded-none border-[#a3e635]/30 bg-black/25 text-xs text-[#f4f4f5]" /></div>}</div><PeerTable peers={rankedPeers} peerId={peerId} ownOffset={ownPeer?.offsetMs ?? estimate?.offsetMs ?? 0} ownUncertainty={ownPeer?.uncertaintyMs ?? estimate?.uncertaintyMs ?? Infinity} /></section>
        <section className="cyber-card p-5 xl:col-span-5"><SectionLabel icon={Gauge}>ROOM LEADERBOARD / STABILITY INDEX</SectionLabel><p className="mt-2 text-xs leading-relaxed text-[#a1a1aa]">Stability rewards a larger retained sample base and penalizes observed offset jitter; it is not a hardware-clock certification.</p><div className="mt-4 overflow-hidden border border-[#a3e635]/15">{rankedPeers.length ? rankedPeers.map((peer, index) => { const score = calculateStabilityScore(peer.jitterMs, peer.sampleCount); return <div key={peer.id} className="numeric grid grid-cols-[26px_1fr_auto] items-center gap-2 border-b border-[#a3e635]/10 px-3 py-2.5 text-xs last:border-0"><span className="text-[#71717a]">{String(index + 1).padStart(2, "0")}</span><div><div className={peer.id === peerId ? "text-[#a3e635]" : "text-[#e4e4e7]"}>{peer.id}{peer.id === peerId ? " / YOU" : ""}</div><div className="mt-1 text-[10px] text-[#71717a]">|offset| {formatOffset(Math.abs(peer.offsetMs))} {formatUncertainty(peer.uncertaintyMs)}</div></div><div className="text-right"><div className="text-[#a3e635]">{score}/100</div><div className="mt-1 text-[10px] text-[#71717a]">{formatNumber(peer.jitterMs)}ms jitter {formatUncertainty(peer.uncertaintyMs)}</div></div></div>; }) : <div className="numeric p-6 text-center text-xs text-[#71717a]">JOIN A ROOM TO BEGIN AN ANONYMOUS COMPARISON</div>}</div></section>
        <section className="cyber-card p-5 xl:col-span-12"><div className="flex flex-wrap items-start justify-between gap-4"><div><SectionLabel icon={Globe2}>WORLD TIME RACK / ALL IANA ZONES</SectionLabel><p className="mt-2 text-xs leading-relaxed text-[#a1a1aa]">Every available IANA zone is searchable through this browser’s internationalization catalog. The picker windows its results rather than rendering the entire catalog, and each display derives from the corrected UTC estimate shown above.</p></div><div className="numeric text-[10px] text-[#a3e635]">{allTimezones.length} ZONES AVAILABLE / {formatUncertainty(totalUncertainty)}</div></div><div className="mt-4 grid gap-4 lg:grid-cols-[.75fr_1.25fr]"><div><div className="relative"><Search className="pointer-events-none absolute left-3 top-2.5 h-4 w-4 text-[#71717a]" /><Input value={timezoneSearch} onChange={event => { setTimezoneSearch(event.target.value); setTimezonePickerScrollTop(0); }} placeholder="Search IANA zone, e.g. Kolkata" className="h-9 rounded-none border-[#a3e635]/30 bg-black/25 pl-9 text-xs text-[#f4f4f5]" /></div><div onScroll={event => setTimezonePickerScrollTop(event.currentTarget.scrollTop)} className="mt-2 h-[248px] overflow-y-auto border border-[#a3e635]/15 bg-black/20"><div style={{ height: `${filteredTimezones.length * TIMEZONE_PICKER_ROW_HEIGHT}px`, position: "relative" }}><div style={{ position: "absolute", left: 0, right: 0, transform: `translateY(${timezoneWindow.start * TIMEZONE_PICKER_ROW_HEIGHT}px)` }}>{timezoneWindow.items.map(zone => <button key={zone} type="button" onClick={() => addWorldZone(zone)} className="flex w-full items-center justify-between border-b border-[#a3e635]/10 px-3 text-left text-xs text-[#d4d4d8] hover:bg-[#a3e635]/10 hover:text-[#a3e635]" style={{ height: `${TIMEZONE_PICKER_ROW_HEIGHT}px` }}><span className="numeric">{zone}</span><Plus className="h-3.5 w-3.5" /></button>)}</div></div></div></div><div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{worldZones.map(zone => <div key={zone} className="border border-[#a3e635]/15 bg-black/20 p-3"><div className="flex items-start justify-between gap-2"><div className="numeric text-[10px] text-[#a3e635]">{zone}</div><button type="button" onClick={() => removeWorldZone(zone)} aria-label={`Remove ${zone}`} className="text-[#71717a] hover:text-red-300"><X className="h-3.5 w-3.5" /></button></div><div className="numeric mt-2 text-sm text-[#f4f4f5]">{formatCorrectedZoneTime(clockEpoch, zone)}</div><div className="numeric mt-1 text-[9px] text-[#71717a]">corrected clock {formatUncertainty(totalUncertainty)}</div></div>)}</div></div></section>
        <section className="cyber-card p-5 xl:col-span-12"><div className="flex flex-wrap items-start justify-between gap-4"><div><SectionLabel icon={ServerCog}>TIME-SOURCE EXPLORER / A + B + C</SectionLabel><p className="mt-2 max-w-3xl text-xs leading-relaxed text-[#a1a1aa]">A: fixed authorities. B: official regional NTP Pool groups. C: a bounded custom-host check. ChronoMesh resolves custom hostnames to a public IPv4 before sending one UDP/123 probe; IP literals, private destinations, rapid repeats, and high-volume probing are rejected.</p></div><Button variant="outline" size="sm" onClick={() => sourceHealth.refetch()} className="h-8 rounded-none border-[#a3e635]/30 bg-transparent text-[10px] text-[#a3e635] hover:bg-[#a3e635]/10 hover:text-[#a3e635]"><RefreshCw className={`mr-1 h-3.5 w-3.5 ${sourceHealth.isFetching ? "animate-spin" : ""}`} />REFRESH CATALOG</Button></div><div className="mt-4 grid gap-4 xl:grid-cols-3"><SourceTier title="A / CURATED AUTHORITIES" description="Backend reference layer" readings={authoritySources} /><SourceTier title="B / REGIONAL NTP POOL" description="Controlled continent-level representatives" readings={regionalSources} /><div className="border border-[#a3e635]/15 bg-black/20 p-3"><div className="numeric text-[10px] tracking-widest text-[#a3e635]">C / CUSTOM HOST</div><p className="mt-2 text-[10px] leading-relaxed text-[#71717a]">Hostname only. One probe per ten seconds; up to twelve per hour per local session.</p><div className="mt-3 flex gap-2"><Input value={customHost} onChange={event => setCustomHost(event.target.value)} placeholder="ntp.example.net" aria-label="Custom NTP hostname" className="h-8 rounded-none border-[#a3e635]/30 bg-black/25 text-xs text-[#f4f4f5]" /><Button disabled={customProbe.isPending} onClick={() => customProbe.mutate({ sessionId, host: customHost })} className="h-8 rounded-none bg-[#a3e635] px-3 font-mono text-[10px] font-bold text-black hover:bg-[#bef264]">{customProbe.isPending ? "PROBING" : "PROBE"}</Button></div>{customResult && <div className="mt-3"><SourceReadingCard reading={customResult} /></div>}{customProbe.isError && <div className="mt-3 text-[10px] text-red-300">{customProbe.error.message}</div>}</div></div></section>
        <section className="cyber-card p-5 xl:col-span-5"><div className="flex items-start justify-between gap-3"><div><SectionLabel icon={UserRound}>SAVED PROFILE / PRIVATE BY DEFAULT</SectionLabel><p className="mt-2 text-xs leading-relaxed text-[#a1a1aa]">Sign in to retain your alert boundary, selected world zones, and optional local hardware template. Public ranking uses a separate anonymous setup label and never publishes room IDs, descriptions, or raw peer identity.</p></div><div className="numeric text-right text-[10px] text-[#a3e635]">{isAuthenticated ? `SIGNED IN / ${user?.name ?? "OPERATOR"}` : "LOCAL ONLY"}</div></div><div className="mt-4 flex flex-wrap gap-2"><Button onClick={persistProfile} disabled={saveProfile.isPending} className="h-9 rounded-none bg-[#a3e635] px-3 font-mono text-[10px] font-bold text-black hover:bg-[#bef264]"><Save className="mr-2 h-3.5 w-3.5" />{isAuthenticated ? "SAVE PREFERENCES" : "SIGN IN TO SAVE"}</Button><button type="button" onClick={() => setSaveHardwareTemplate(value => !value)} className={`numeric border px-3 text-[10px] ${saveHardwareTemplate ? "border-[#a3e635]/40 bg-[#a3e635]/10 text-[#a3e635]" : "border-[#52525b] text-[#a1a1aa]"}`}>{saveHardwareTemplate ? "HARDWARE TEMPLATE ON" : "HARDWARE TEMPLATE OFF"}</button><button type="button" onClick={() => setHighContrastMode(value => !value)} className={`numeric border px-3 text-[10px] ${highContrastMode ? "border-white bg-white text-black" : "border-[#52525b] text-[#a1a1aa]"}`}>{highContrastMode ? "HIGH-CONTRAST ACTIVE" : "ENABLE HIGH CONTRAST"}</button></div><div className="mt-4 border-t border-[#a3e635]/15 pt-3"><div className="flex flex-wrap items-center justify-between gap-2"><div className="numeric text-[10px] tracking-widest text-[#a3e635]">PUBLIC STABILITY LEADERBOARD / EXPLICIT OPT-IN</div><button type="button" onClick={() => setPublicLeaderboardOptIn(value => !value)} className={`numeric border px-2 py-1 text-[10px] ${publicLeaderboardOptIn ? "border-[#a3e635]/40 bg-[#a3e635]/10 text-[#a3e635]" : "border-[#52525b] text-[#a1a1aa]"}`}>{publicLeaderboardOptIn ? "OPTED IN" : "PRIVATE"}</button></div>{publicLeaderboardOptIn && <div className="mt-2 flex flex-wrap gap-2"><Input value={publicSetupLabel} onChange={event => setPublicSetupLabel(event.target.value)} maxLength={48} placeholder="Anonymous setup label, e.g. GPSDO / PPS" aria-label="Public anonymous setup label" className="numeric h-8 flex-1 rounded-none border-[#a3e635]/30 bg-black/25 text-xs text-[#f4f4f5]" /><Button onClick={publishCurrentStability} disabled={publishPublicStability.isPending} className="h-8 rounded-none bg-[#a3e635] px-3 font-mono text-[10px] font-bold text-black hover:bg-[#bef264]"><Trophy className="mr-1 h-3.5 w-3.5" />PUBLISH CURRENT</Button></div>}<p className="mt-2 text-[10px] leading-relaxed text-[#71717a]">Only the label, saved tags, aggregate stability score, offset, jitter, uncertainty, and sample count are public. Saving with PRIVATE removes your listing.</p></div><div className="numeric mt-3 text-[10px] text-[#71717a]">{saveHardwareTemplate ? "TEMPLATE STORED ONLY IN YOUR SIGNED-IN PROFILE" : "NO HARDWARE CONTEXT WILL BE SAVED"}</div></section>
        <section className="cyber-card p-5 xl:col-span-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><SectionLabel icon={Waves}>SOURCE ACCURACY HISTORY</SectionLabel><p className="mt-2 text-xs leading-relaxed text-[#a1a1aa]">Measured server-side source snapshots, summarized by availability, median offset, jitter, and uncertainty. Empty periods remain empty rather than inferred.</p></div><div className="flex gap-1">{(["24h", "7d", "30d"] as AnalyticsRange[]).map(range => <button key={range} type="button" onClick={() => setAnalyticsRange(range)} className={`numeric border px-2 py-1 text-[10px] ${analyticsRange === range ? "border-[#a3e635]/40 bg-[#a3e635]/10 text-[#a3e635]" : "border-[#52525b] text-[#a1a1aa]"}`}>{range.toUpperCase()}</button>)}</div></div><div className="mt-4 grid gap-4 lg:grid-cols-[1.1fr_.9fr]"><div className="h-[190px] border border-[#a3e635]/15 bg-black/20 p-3"><ResponsiveContainer width="100%" height="100%"><LineChart data={analyticsTimeline}><CartesianGrid stroke="rgba(163,230,53,.10)" strokeDasharray="2 4" vertical={false} /><XAxis dataKey="time" tick={{ fill: "#71717a", fontSize: 9 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "#71717a", fontSize: 9 }} axisLine={false} tickLine={false} width={40} /><Tooltip contentStyle={{ background: "#111210", border: "1px solid rgba(163,230,53,.35)", fontFamily: "monospace", fontSize: 11 }} /><Line connectNulls type="monotone" dataKey="medianOffsetMs" name="median offset ms" stroke="#a3e635" strokeWidth={2} dot={false} /></LineChart></ResponsiveContainer></div><div className="max-h-[190px] overflow-y-auto border border-[#a3e635]/15 bg-black/20">{analytics.data?.sources.length ? analytics.data.sources.map(source => <div key={source.id} className="grid grid-cols-[1fr_auto] gap-2 border-b border-[#a3e635]/10 p-2.5 text-xs last:border-0"><div><div className="text-[#e4e4e7]">{source.name}</div><div className="numeric mt-1 text-[9px] text-[#71717a]">{source.samples} SAMPLES / JITTER {source.jitterMs === null ? "—" : `${formatNumber(source.jitterMs)} ms`}</div></div><div className="numeric text-right"><div className="text-[#a3e635]">{formatOffset(source.medianOffsetMs)} {formatUncertainty(source.medianUncertaintyMs)}</div><div className="mt-1 text-[9px] text-[#a1a1aa]">{formatNumber(source.availabilityPct, 1)}% UP</div></div></div>) : <div className="numeric p-6 text-center text-[10px] text-[#71717a]">NO SNAPSHOTS IN THIS WINDOW</div>}</div></div><div className="mt-4 border border-[#a3e635]/25 bg-[#a3e635]/[.035] p-3"><div className="flex items-center justify-between gap-3"><SectionLabel icon={Sparkles}>AI SOURCE-HISTORY INTERPRETER</SectionLabel><button type="button" onClick={() => sourceInsight.refetch()} className="numeric border border-[#a3e635]/30 px-2 py-1 text-[9px] text-[#a3e635]">REFRESH</button></div>{sourceInsight.isLoading ? <div className="numeric mt-3 text-[10px] text-[#71717a]">READING MEASURED HISTORY…</div> : <><p className="mt-3 text-xs leading-relaxed text-[#d4d4d8]">{sourceInsight.data?.value.summary ?? "No automated summary is available."}</p><div className="numeric mt-3 flex flex-wrap gap-2 text-[9px]"><span className="border border-[#a3e635]/25 px-1.5 py-1 text-[#a3e635]">JITTER {sourceInsight.data?.value.jitterTrend.replaceAll("_", " ").toUpperCase() ?? "—"}</span><span className="border border-[#a3e635]/25 px-1.5 py-1 text-[#a3e635]">OFFSET {sourceInsight.data?.value.offsetAssessment.replaceAll("_", " ").toUpperCase() ?? "—"}</span>{sourceInsight.data?.cached && <span className="text-[#71717a]">CACHED ≤ 5 MIN</span>}</div><div className="mt-2 text-[10px] leading-relaxed text-[#a1a1aa]">Evidence: {sourceInsight.data?.value.evidence.map(item => `${item.source} ${item.metric}=${formatNumber(item.value)}`).join(" · ") ?? "none"}. Limitation: {sourceInsight.data?.value.limitation ?? "No substitute for the raw measurements."}</div></>}</div></section>
        <section className="cyber-card p-5 xl:col-span-12"><div className="grid gap-5 lg:grid-cols-[.9fr_1.1fr] lg:items-start"><div><SectionLabel icon={ShieldCheck}>HONEST PRECISION / LIMITS DISCLOSED</SectionLabel><div className="mt-4 grid gap-2 sm:grid-cols-2"><Metric label="BROWSER CONTEXT" value={window.crossOriginIsolated ? "ISOLATED" : "DEFAULT"} detail={window.crossOriginIsolated ? "COOP + COEP active" : "reduced timer precision"} /><Metric label="OBSERVED TIMER STEP" value={timerResolutionUs ? `${formatNumber(timerResolutionUs, 1)} µs` : "measuring"} detail={timerResolutionUs ? `± ${formatNumber(timerResolutionUs, 1)} µs floor` : "± pending"} /><Metric label="NETWORK ENVELOPE" value={estimate ? `${formatNumber(estimate.delayMs)} ms` : "pending"} detail={estimate ? formatUncertainty(estimate.uncertaintyMs) : "± pending"} /><Metric label="DISPLAY FRACTION" value="µs interpolated" detail="± not nanosecond accuracy" /></div></div><div className="space-y-3 border-l-0 border-[#a3e635]/15 lg:border-l lg:pl-5"><p className="text-sm leading-relaxed text-[#d4d4d8]">A browser can display sub-millisecond digits, but public-network synchronization is limited by packet delay asymmetry, operating-system scheduling, Wi-Fi/mobile jitter, and browser timer policy. ChronoMesh renders every clock and offset as an estimate <span className="numeric text-[#a3e635]">value ± uncertainty</span>.</p><p className="text-xs leading-relaxed text-[#a1a1aa]">For a peer comparison, the useful number is relative offset to a common server. For genuine nanosecond-class work, use hardware timestamping, PTP-capable equipment, and a disciplined GPS/PPS reference; this web experience does not claim that level of accuracy.</p><div className="numeric flex flex-wrap items-center gap-2 text-[10px] text-[#71717a]"><Database className="h-3.5 w-3.5 text-[#a3e635]" />PRIMARY TRANSPORT: {diagnostics.data?.primaryTransport?.toUpperCase() ?? "CHECKING"} / MANAGED PUBSUB {diagnostics.data?.managedPubSub ? "ONLINE" : "UNAVAILABLE"} / DATABASE RELAY {diagnostics.data?.databaseRelay ? "ARMED" : "BYPASSED"} / LOCAL ROOMS {diagnostics.data?.activeRooms ?? 0}</div></div></div></section>
      </div>
    </main><footer className="border-t border-[#a3e635]/10 px-5 py-5 text-center numeric text-[10px] tracking-[.14em] text-[#52525b]">CHRONOMESH / GLOBAL CLOCK COMPARISON / MEASUREMENT OVER CLAIMS</footer>
  </div>;
}

function Metric({ label, value, detail }: { label: string; value: string; detail: string }) { return <div className="border border-[#a3e635]/14 bg-black/20 p-2.5"><div className="numeric text-[9px] tracking-[.12em] text-[#71717a]">{label}</div><div className="numeric mt-1 truncate text-xs font-medium text-[#e4e4e7]">{value}</div><div className="numeric mt-1 text-[9px] text-[#a3e635]">{detail}</div></div>; }
type GlobalMeshPanelData = { generatedAt: number; consensus: { fusedOffsetMs: number | null; fusedUncertaintyMs: number | null; contributorCount: number; independentGroupCount: number; eligibleCount: number; rejectedCount: number; qualityState: "healthy" | "degraded" | "unavailable" }; sourceCounts: { configured: number; active: number; pending: number; paused: number; quarantined: number }; sources: Array<{ id: string; displayName: string; sourceClass: string; state: string; provenance: string; publicLabel: string | null; region: string | null; lastProbeAtMs: number | null; quality: { reachableSamples: number; totalSamples: number; medianUncertaintyMs: number | null; medianDelayMs: number | null } | null }> };
type CommunityManagedSource = { id: string; displayName: string; host: string; state: "pending" | "active" | "paused" | "quarantined" | "withdrawn"; publicMetadataOptIn: boolean; verificationMethod: string; region: string | null };
function LegacyGlobalSourceMeshPanel({ mesh, isLoading, isAuthenticated, communitySources, host, name, region, isPublic, verificationToken, isRegistering, onHostChange, onNameChange, onRegionChange, onPublicChange, onRegister, onVerify, onSetState }: { mesh?: GlobalMeshPanelData; isLoading: boolean; isAuthenticated: boolean; communitySources: CommunityManagedSource[]; host: string; name: string; region: string; isPublic: boolean; verificationToken: string | null; isRegistering: boolean; onHostChange: (value: string) => void; onNameChange: (value: string) => void; onRegionChange: (value: string) => void; onPublicChange: (value: boolean) => void; onRegister: () => void; onVerify: (sourceId: string) => void; onSetState: (sourceId: string, state: "paused" | "withdrawn") => void }) {
  const consensus = mesh?.consensus;
  const qualityTone = consensus?.qualityState === "healthy" ? "border-[#a3e635]/45 bg-[#a3e635]/10 text-[#a3e635]" : consensus?.qualityState === "degraded" ? "border-amber-300/45 bg-amber-300/10 text-amber-200" : "border-red-400/45 bg-red-400/10 text-red-200";
  const [sourceClassFilter, setSourceClassFilter] = useState("all");
  const [sourceStateFilter, setSourceStateFilter] = useState("active");
  const [sourceRegionFilter, setSourceRegionFilter] = useState("all");
  const regions = useMemo(() => Array.from(new Set((mesh?.sources ?? []).flatMap(source => source.region ? [source.region] : []))).sort(), [mesh?.sources]);
  const filteredSources = (mesh?.sources ?? []).filter(source => (sourceClassFilter === "all" || source.sourceClass === sourceClassFilter) && (sourceStateFilter === "all" || source.state === sourceStateFilter) && (sourceRegionFilter === "all" || source.region === sourceRegionFilter));
  return <section className="cyber-card mb-5 overflow-hidden p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><SectionLabel icon={Database}>GLOBAL SOURCE MESH / BOUNDED CONSENSUS</SectionLabel><p className="mt-2 max-w-3xl text-xs leading-relaxed text-[#a1a1aa]">ChronoMesh does not attempt to scan the internet. It keeps a verified, opt-in registry, rotates a quota-limited probe cohort, and fuses independent sources only after delay, uncertainty, outlier, and duplicate-operator controls.</p></div><div className={`numeric border px-2 py-1 text-[10px] ${qualityTone}`}>{consensus?.qualityState?.toUpperCase() ?? (isLoading ? "LOADING" : "UNAVAILABLE")}</div></div><div className="mt-4 grid gap-4 xl:grid-cols-[1.15fr_.85fr]"><div className="border border-[#a3e635]/15 bg-black/20 p-4"><div className="grid gap-3 sm:grid-cols-4"><Metric label="FUSED OFFSET" value={formatOffset(consensus?.fusedOffsetMs)} detail={formatUncertainty(consensus?.fusedUncertaintyMs)} /><Metric label="INDEPENDENT" value={String(consensus?.independentGroupCount ?? 0)} detail="operator groups" /><Metric label="ELIGIBLE" value={String(consensus?.eligibleCount ?? 0)} detail={`rejected ${consensus?.rejectedCount ?? 0}`} /><Metric label="ACTIVE SOURCES" value={String(mesh?.sourceCounts.active ?? 0)} detail={`catalog ${mesh?.sourceCounts.configured ?? 0}`} /></div><div className="mt-4 overflow-x-auto border border-[#a3e635]/12"><table className="w-full min-w-[560px] numeric text-left text-[10px]"><thead className="bg-[#a3e635]/5 text-[9px] tracking-[.12em] text-[#a1a1aa]"><tr><th className="px-3 py-2">PUBLIC SOURCE LABEL</th><th className="px-3 py-2">CLASS</th><th className="px-3 py-2">STATE</th><th className="px-3 py-2">REGION</th><th className="px-3 py-2">PROVENANCE</th></tr></thead><tbody>{mesh?.sources.length ? mesh.sources.slice(0, 12).map(source => <tr key={source.id} className="border-t border-[#a3e635]/10"><td className="px-3 py-2 text-[#e4e4e7]">{source.publicLabel ?? source.displayName}</td><td className="px-3 py-2 text-[#a3e635]">{source.sourceClass.replaceAll("_", " ")}</td><td className="px-3 py-2 text-[#d4d4d8]">{source.state}</td><td className="px-3 py-2 text-[#71717a]">{source.region ?? "—"}</td><td className="px-3 py-2 text-[#71717a]">{source.provenance.replaceAll("_", " ")}</td></tr>) : <tr><td className="px-3 py-6 text-center text-[#71717a]" colSpan={5}>{isLoading ? "ASSEMBLING THE BOUNDED SOURCE COHORT…" : "NO SOURCE-REGISTRY TELEMETRY YET."}</td></tr>}</tbody></table></div><p className="mt-3 text-[10px] leading-relaxed text-[#71717a]">A source’s hostname, operator identity, and verification token are never included in this public mesh view unless that operator has explicitly opted in to the displayed label.</p></div><div className="border border-[#a3e635]/15 bg-black/20 p-4"><SectionLabel icon={ShieldCheck}>CONTRIBUTE A COMMUNITY NTP SOURCE</SectionLabel>{!isAuthenticated ? <div className="mt-4"><p className="text-xs leading-relaxed text-[#a1a1aa]">Sign in to submit a hostname you operate. The source remains pending until a DNS TXT ownership check succeeds; it is never automatically trusted or publicly named.</p><Button onClick={() => startLogin()} className="mt-3 h-8 rounded-none bg-[#a3e635] px-3 font-mono text-[10px] font-bold text-black hover:bg-[#bef264]">SIGN IN TO CONTRIBUTE</Button></div> : <><p className="mt-2 text-[10px] leading-relaxed text-[#71717a]">Hostname only—no IP literals. A rotating cohort limits probe volume and failed probes back off exponentially.</p><div className="mt-3 grid gap-2"><Input value={host} onChange={event => onHostChange(event.target.value)} placeholder="ntp.example.org" aria-label="Community NTP hostname" className="h-8 rounded-none border-[#a3e635]/30 bg-black/25 text-xs text-[#f4f4f5]" /><Input value={name} onChange={event => onNameChange(event.target.value)} placeholder="Private operator label" aria-label="Community source private label" className="h-8 rounded-none border-[#a3e635]/30 bg-black/25 text-xs text-[#f4f4f5]" /><Input value={region} onChange={event => onRegionChange(event.target.value)} placeholder="Optional region, e.g. APAC" aria-label="Community source region" className="h-8 rounded-none border-[#a3e635]/30 bg-black/25 text-xs text-[#f4f4f5]" /></div><label className="mt-3 flex cursor-pointer items-center gap-2 text-[10px] text-[#a1a1aa]"><input type="checkbox" checked={isPublic} onChange={event => onPublicChange(event.target.checked)} className="accent-[#a3e635]" />Publish this label in the public registry after verification</label><Button disabled={isRegistering || host.trim().length < 3 || name.trim().length < 2} onClick={onRegister} className="mt-3 h-8 w-full rounded-none bg-[#a3e635] px-3 font-mono text-[10px] font-bold text-black hover:bg-[#bef264]">{isRegistering ? "REGISTERING" : "REGISTER HOSTNAME"}</Button>{verificationToken && <div className="mt-3 border border-amber-300/30 bg-amber-300/5 p-2 text-[10px] text-amber-100"><div className="numeric text-amber-300">DNS TXT SETUP / PRIVATE TOKEN</div><code className="mt-1 block break-all select-all">_chronomesh.&lt;your-host&gt; = chronomesh-verify={verificationToken}</code></div>}<div className="mt-4 space-y-2">{communitySources.length ? communitySources.map(source => <div key={source.id} className="border border-[#a3e635]/12 p-2"><div className="flex items-center justify-between gap-2"><span className="numeric truncate text-[10px] text-[#e4e4e7]">{source.host}</span><span className="numeric text-[9px] text-[#a3e635]">{source.state.toUpperCase()}</span></div><div className="mt-2 flex flex-wrap gap-2">{source.state === "pending" && <Button onClick={() => onVerify(source.id)} size="sm" className="h-6 rounded-none bg-[#a3e635] px-2 font-mono text-[9px] text-black hover:bg-[#bef264]">VERIFY DNS</Button>}{source.state === "active" && <Button onClick={() => onSetState(source.id, "paused")} size="sm" variant="outline" className="h-6 rounded-none border-amber-300/35 px-2 font-mono text-[9px] text-amber-200">PAUSE</Button>}{source.state !== "withdrawn" && <Button onClick={() => onSetState(source.id, "withdrawn")} size="sm" variant="outline" className="h-6 rounded-none border-red-400/35 px-2 font-mono text-[9px] text-red-300">WITHDRAW</Button>}</div></div>) : <div className="numeric py-2 text-[10px] text-[#71717a]">NO COMMUNITY HOSTNAMES REGISTERED.</div>}</div></>}</div></div></section>;
}
function FormulaPanel({ sample, timerResolutionUs }: { sample?: TimeProbe; timerResolutionUs: number | null }) { return <div className="border border-[#a3e635]/15 bg-black/20 p-3"><div className="flex items-center justify-between"><span className="numeric text-[10px] tracking-widest text-[#a1a1aa]">T1–T4 OFFSET SOLVER</span><TimerReset className="h-4 w-4 text-[#a3e635]" /></div><div className="mt-3 grid grid-cols-2 gap-2">{([ ["T1", sample?.t1, "client send"], ["T2", sample?.t2, "server receive"], ["T3", sample?.t3, "server send"], ["T4", sample?.t4, "client receive"] ] as const).map(([label, value, description]) => <div key={label} className="border border-[#a3e635]/10 p-2"><div className="numeric text-[10px] text-[#a3e635]">{label}</div><div className="numeric mt-1 text-[11px] text-[#d4d4d8]">{value ? `${Math.round(value)} ms` : "—"}</div><div className="mt-1 text-[9px] text-[#71717a]">{description} {formatUncertainty(timerResolutionUs ? timerResolutionUs / 1000 : null)}</div></div>)}</div><div className="numeric mt-3 border-l-2 border-[#a3e635] bg-[#a3e635]/5 p-2 text-[10px] leading-relaxed text-[#d4d4d8]">offset = ((T2 − T1) + (T3 − T4)) / 2<br />delay = (T4 − T1) − (T3 − T2)<br /><span className="text-[#a3e635]">{sample ? `solution: ${formatOffset(sample.offsetMs)} ${formatUncertainty(sample.delayMs / 2)}` : "run a burst to solve"}</span></div></div>; }
function RawSamplesTable({ samples, retained, timerResolutionUs }: { samples: TimeProbe[]; retained: Set<number>; timerResolutionUs: number | null }) { return <div className="mt-5 overflow-x-auto border border-[#a3e635]/15"><table className="w-full min-w-[700px] numeric text-left text-[11px]"><thead className="bg-[#a3e635]/5 text-[9px] tracking-[.14em] text-[#a1a1aa]"><tr><th className="px-3 py-2">PROBE</th><th className="px-3 py-2">OFFSET (± UNCERTAINTY)</th><th className="px-3 py-2">DELAY / RTT</th><th className="px-3 py-2">T1 → T4 WINDOW</th><th className="px-3 py-2">FILTER</th></tr></thead><tbody>{samples.length ? samples.map(sample => <tr key={sample.sampleIndex} className="border-t border-[#a3e635]/10"><td className="px-3 py-2 text-[#e4e4e7]">#{String(sample.sampleIndex).padStart(2, "0")}</td><td className="px-3 py-2 text-[#a3e635]">{formatOffset(sample.offsetMs)} {formatUncertainty(sample.delayMs / 2)}</td><td className="px-3 py-2 text-[#d4d4d8]">{formatNumber(sample.delayMs)} ms / {formatNumber(sample.rttMs)} ms {formatUncertainty(timerResolutionUs ? timerResolutionUs / 1000 : null)}</td><td className="px-3 py-2 text-[#71717a]">{Math.round(sample.t1)} → {Math.round(sample.t4)} ms {formatUncertainty(timerResolutionUs ? timerResolutionUs / 1000 : null)}</td><td className="px-3 py-2">{retained.has(sample.sampleIndex) ? <span className="border border-[#a3e635]/35 bg-[#a3e635]/10 px-1.5 py-0.5 text-[9px] text-[#a3e635]">RETAINED</span> : <span className="text-[#71717a]">REJECTED BY DELAY</span>}</td></tr>) : <tr><td colSpan={5} className="px-3 py-8 text-center text-[#71717a]">COLLECTING INITIAL PROBES…</td></tr>}</tbody></table></div>; }
function AuthorityRow({ reading }: { reading: SourceReading }) { return <SourceReadingCard reading={reading} compact />; }
function SourceReadingCard({ reading, compact = false }: { reading: SourceReading; compact?: boolean }) { const unavailableLabel = reading.status === "blocked" ? "BLOCKED" : "UNREACHABLE"; return <div className={`grid grid-cols-[1fr_auto] items-center gap-3 border border-[#a3e635]/12 bg-black/15 p-3 ${compact ? "" : "mb-2"}`}><div><div className="flex items-center gap-2"><span className={`h-1.5 w-1.5 rounded-full ${reading.status === "reachable" ? "bg-[#a3e635]" : reading.status === "blocked" ? "bg-amber-300" : "bg-red-400"}`} /><span className="text-xs font-medium text-[#e4e4e7]">{reading.name}</span></div><div className="numeric mt-1 text-[10px] text-[#71717a]">{reading.host} / {reading.status === "reachable" ? `RTT ${formatNumber(reading.delayMs ?? NaN)} ms` : unavailableLabel}</div></div><div className="numeric text-right text-[11px]"><div className={reading.status === "reachable" ? "text-[#a3e635]" : reading.status === "blocked" ? "text-amber-300" : "text-red-300"}>{reading.status === "reachable" ? formatOffset(reading.offsetMs) : unavailableLabel}</div><div className="mt-1 text-[9px] text-[#a1a1aa]">{reading.status === "reachable" ? formatUncertainty(reading.uncertaintyMs) : reading.detail ?? "No value substituted."}</div></div></div>; }
function SourceTier({ title, description, readings }: { title: string; description: string; readings: SourceReading[] }) { return <div className="border border-[#a3e635]/15 bg-black/20 p-3"><div className="numeric text-[10px] tracking-widest text-[#a3e635]">{title}</div><p className="mt-1 text-[10px] text-[#71717a]">{description}</p><div className="mt-3 max-h-[300px] overflow-y-auto">{readings.length ? readings.map(reading => <SourceReadingCard key={reading.id} reading={reading} />) : <div className="numeric py-8 text-center text-[10px] text-[#71717a]">QUERYING SOURCES…</div>}</div></div>; }
function PeerComparisonTooltip({ active, payload, label, leaders, visibleSeries }: { active?: boolean; payload?: Array<{ payload?: Record<string, number> }>; label?: number; leaders: ReturnType<typeof getTopComparisonSetups>; visibleSeries: Record<string, boolean> }) {
  if (!active || !payload?.[0]?.payload) return null;
  const point = payload[0].payload;
  const rows = getConsentedTooltipRows(point, leaders.map(leader => ({ ...leader, isConsented: true })), visibleSeries);
  return <div className="max-w-[280px] border border-[#a3e635]/35 bg-[#111210] p-2.5 numeric text-[10px] shadow-xl"><div className="text-[#a3e635]">{new Date(Number(label)).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" })}</div>{visibleSeries.localOffsetMs !== false && <div className="mt-2 flex justify-between gap-4 text-[#e4e4e7]"><span>YOU / LIVE ROOM</span><span>{formatOffset(point.localOffsetMs)}</span></div>}{rows.map(row => <div key={row.label} className="mt-2 border-t border-[#a3e635]/10 pt-2"><div className="flex justify-between gap-4 text-[#d4d4d8]"><span>{row.label}</span><span>{formatOffset(row.offsetMs)}</span></div><div className="mt-1 text-[#71717a]">TAGS: {row.hardwareTags.length ? row.hardwareTags.join(" · ") : "none"} / {formatUncertainty(row.uncertaintyMs)}</div></div>)}</div>;
}
function AuthorityComparisonTooltip({ active, payload, label, readings }: { active?: boolean; payload?: Array<{ payload?: AuthorityTelemetryPoint }>; label?: number; readings: SourceReading[] }) {
  if (!active || !payload?.[0]?.payload) return null;
  const rows = getAuthorityTooltipRows(payload[0].payload, readings);
  if (!rows.length) return null;
  return <div className="max-w-[300px] border border-[#a3e635]/35 bg-[#111210] p-2.5 numeric text-[10px] shadow-xl"><div className="text-[#a3e635]">{new Date(Number(label)).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" })}</div>{rows.map(row => <div key={row.id} className="mt-2 border-t border-[#a3e635]/10 pt-2"><div className="flex justify-between gap-4 text-[#e4e4e7]"><span>{row.name}</span><span>{formatOffset(row.offsetMs)}</span></div><div className="mt-1 text-[#71717a]">RTT / TIME TAKEN {formatNumber(row.delayMs ?? NaN)} ms · {formatUncertainty(row.uncertaintyMs)}</div></div>)}</div>;
}
function AuthorityComparisonChart({ trace, readings }: { trace: AuthorityTelemetryPoint[]; readings: SourceReading[] }) {
  const colors = ["#a3e635", "#38bdf8", "#fbbf24", "#f472b6"];
  return <div className="mt-4 border border-[#a3e635]/15 bg-black/20 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><div className="numeric text-[10px] tracking-widest text-[#a3e635]">LIVE AUTHORITY OFFSET / NETWORK TIME TAKEN</div><span className="numeric text-[9px] text-[#71717a]">SERVER-SIDE SAMPLES / 15s REFRESH</span></div><p className="mt-1 text-[10px] leading-relaxed text-[#71717a]">Lines show this backend clock’s measured offset to Cloudflare, Google, NIST, and NTP Pool. Hover to inspect the separate UDP NTP round-trip delay—the observed network time taken—and uncertainty.</p><div className="mt-3 h-[210px]">{trace.length ? <ResponsiveContainer width="100%" height="100%"><LineChart data={trace}><CartesianGrid stroke="rgba(163,230,53,.10)" strokeDasharray="2 4" vertical={false} /><XAxis dataKey="timestamp" tickFormatter={value => new Date(value).toLocaleTimeString([], { minute: "2-digit", second: "2-digit" })} tick={{ fill: "#71717a", fontSize: 9 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "#71717a", fontSize: 9 }} axisLine={false} tickLine={false} width={44} /><Tooltip content={<AuthorityComparisonTooltip readings={readings} />} /><Line type="monotone" dataKey={authoritySeriesKey("cloudflare", "offset")} name="Cloudflare offset" stroke={colors[0]} strokeWidth={2} dot={false} className="chart-series-line" isAnimationActive animationDuration={220} animationEasing="ease-out" />{["google", "nist", "ntp_pool"].map((id, index) => <Line key={id} type="monotone" dataKey={authoritySeriesKey(id, "offset")} name={`${id} offset`} stroke={colors[index + 1]} strokeWidth={1.5} dot={false} className="chart-series-line" isAnimationActive animationDuration={220} animationEasing="ease-out" />)}</LineChart></ResponsiveContainer> : <div className="grid h-full place-items-center border border-dashed border-[#a3e635]/20"><span className="numeric text-[10px] text-[#71717a]">WAITING FOR A REACHABLE AUTHORITY SAMPLE…</span></div>}</div></div>;
}
function EnhancedPeerTable({ peers, peerId, ownOffset, ownUncertainty }: { peers: Peer[]; peerId: string | null; ownOffset: number; ownUncertainty: number }) {
  const publicComparison = trpc.chronomesh.publicStabilityLeaderboard.useQuery({ limit: 3 }, { staleTime: 30_000, refetchInterval: 30_000 });
  const authorityHealth = trpc.chronomesh.upstreamHealth.useQuery(undefined, { staleTime: 12_000, refetchInterval: 15_000, retry: 1 });
  const topSetups = useMemo(() => getTopComparisonSetups(publicComparison.data ?? [], 3), [publicComparison.data]);
  const [trace, setTrace] = useState<Array<Record<string, number>>>([]);
  const [authorityTrace, setAuthorityTrace] = useState<AuthorityTelemetryPoint[]>([]);
  const [visibleSeries, setVisibleSeries] = useState<Record<string, boolean>>({});
  const [reduceMotion, setReduceMotion] = useState(false);
  const availableSeries = useMemo(() => ["localOffsetMs", ...topSetups.map((_, index) => `leader_${index}`)], [topSetups]);
  useEffect(() => { setVisibleSeries(current => reconcileSeriesVisibility(current, availableSeries)); }, [availableSeries]);
  useEffect(() => { const media = window.matchMedia("(prefers-reduced-motion: reduce)"); const sync = () => setReduceMotion(media.matches); sync(); media.addEventListener("change", sync); return () => media.removeEventListener("change", sync); }, []);
  useEffect(() => { document.documentElement.style.setProperty("--chronomesh-chart-transition-ms", `${getChartSeriesTransition(true, reduceMotion).animationDuration}ms`); }, [reduceMotion]);
  useEffect(() => { if (Number.isFinite(ownOffset) && topSetups.length) setTrace(current => [...current.slice(-59), buildPeerComparisonPoint(Date.now(), ownOffset, topSetups)]); }, [ownOffset, topSetups]);
  useEffect(() => { const point = buildAuthorityTelemetryPoint(Date.now(), authorityHealth.data?.readings ?? []); if (point) setAuthorityTrace(current => [...current.slice(-59), point]); }, [authorityHealth.dataUpdatedAt]);
  const seriesControls = [{ key: "localOffsetMs", label: "YOU / LIVE ROOM", color: "#a3e635" }, ...topSetups.map((setup, index) => ({ key: `leader_${index}`, label: setup.setupLabel, color: ["#38bdf8", "#fbbf24", "#f472b6"][index] }))];
  return <>
    <AuthorityComparisonChart trace={authorityTrace} readings={authorityHealth.data?.readings ?? []} />
    <div className="mt-4 border border-[#a3e635]/15 bg-black/20 p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="numeric text-[10px] tracking-widest text-[#a3e635]">LIVE OFFSET / CONSENTED PUBLIC LEADERS</div>
        <span className="numeric text-[9px] text-[#71717a]">YOUR LIVE OFFSET VS TOP {topSetups.length} PUBLIC AGGREGATES</span>
      </div>
      <p className="mt-1 text-[10px] leading-relaxed text-[#71717a]">Hover any timestamp for exact offsets and consented public hardware tags. Controls fade series in and out without changing the underlying measurement data.</p>
      <div className="mt-3 flex flex-wrap gap-2" role="group" aria-label="Comparison chart series visibility">
        {seriesControls.map(series => <button key={series.key} type="button" aria-pressed={visibleSeries[series.key] !== false} onClick={() => setVisibleSeries(current => ({ ...current, [series.key]: current[series.key] === false }))} className={`numeric inline-flex items-center gap-1.5 border px-2 py-1 text-[9px] transition-colors ${visibleSeries[series.key] !== false ? "border-[#a3e635]/45 bg-[#a3e635]/10 text-[#e4e4e7]" : "border-[#52525b] bg-black/20 text-[#71717a]"}`}><span aria-hidden="true" className="h-2 w-2 rounded-full" style={{ backgroundColor: visibleSeries[series.key] !== false ? series.color : "#52525b" }} />{visibleSeries[series.key] !== false ? "HIDE" : "SHOW"} {series.label}</button>)}
      </div>
      <div className="mt-3 h-[190px]">
        {trace.length && topSetups.length ? <ResponsiveContainer width="100%" height="100%"><LineChart data={trace}><CartesianGrid stroke="rgba(163,230,53,.10)" strokeDasharray="2 4" vertical={false} /><XAxis dataKey="timestamp" tickFormatter={value => new Date(value).toLocaleTimeString([], { minute: "2-digit", second: "2-digit" })} tick={{ fill: "#71717a", fontSize: 9 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "#71717a", fontSize: 9 }} axisLine={false} tickLine={false} width={44} /><Tooltip content={<PeerComparisonTooltip leaders={topSetups} visibleSeries={visibleSeries} />} />{seriesControls.map(series => { const transition = getChartSeriesTransition(visibleSeries[series.key] !== false, reduceMotion); return <Line key={series.key} type={series.key === "localOffsetMs" ? "monotone" : "stepAfter"} dataKey={series.key} name={series.label} stroke={series.color} strokeWidth={series.key === "localOffsetMs" ? 2 : 1.5} dot={false} className="chart-series-line" strokeOpacity={transition.strokeOpacity} isAnimationActive={transition.animationDuration > 0} animationDuration={transition.animationDuration} animationEasing="ease-out" />; })}</LineChart></ResponsiveContainer> : <div className="grid h-full place-items-center border border-dashed border-[#a3e635]/20"><span className="numeric text-[10px] text-[#71717a]">JOIN A ROOM, SYNC, AND WAIT FOR A CONSENTED PUBLIC LEADER TRACE.</span></div>}
      </div>
    </div>
    <div className="mt-4 overflow-x-auto border border-[#a3e635]/15"><table className="w-full min-w-[760px] numeric text-left text-[11px]"><thead className="bg-[#a3e635]/5 text-[9px] tracking-[.14em] text-[#a1a1aa]"><tr><th className="px-3 py-2">ANONYMOUS PEER / OPT-IN CONTEXT</th><th className="px-3 py-2">OFFSET → MESH</th><th className="px-3 py-2">RELATIVE → YOU</th><th className="px-3 py-2">JITTER</th><th className="px-3 py-2">CONFIDENCE</th></tr></thead><tbody>{peers.length ? peers.map(peer => { const confidence = deriveConfidence(peer.uncertaintyMs, peer.sampleCount); const relative = peer.offsetMs - ownOffset; const relativeUncertainty = Math.hypot(peer.uncertaintyMs, ownUncertainty); return <tr key={peer.id} className="border-t border-[#a3e635]/10"><td className="px-3 py-2 text-[#e4e4e7]"><div>{peer.id}{peer.id === peerId && <span className="ml-2 text-[#a3e635]">YOU</span>}</div>{peer.tags.length > 0 && <div className="mt-1 flex flex-wrap gap-1">{peer.tags.map(tag => <span key={tag} className="border border-[#a3e635]/25 bg-[#a3e635]/5 px-1 text-[9px] text-[#a3e635]">{tag}</span>)}</div>}{peer.description && <div className="mt-1 max-w-[250px] text-[9px] text-[#71717a]">{peer.description}</div>}</td><td className="px-3 py-2 text-[#a3e635]">{formatOffset(peer.offsetMs)} {formatUncertainty(peer.uncertaintyMs)}</td><td className="px-3 py-2 text-[#e4e4e7]">{formatOffset(relative)} {formatUncertainty(relativeUncertainty)}</td><td className="px-3 py-2 text-[#a1a1aa]">{formatNumber(peer.jitterMs)} ms {formatUncertainty(peer.jitterMs)}</td><td className="px-3 py-2"><span className={`border px-1.5 py-0.5 text-[9px] ${confidenceTone(confidence)}`}>{confidence.toUpperCase()}</span></td></tr>; }) : <tr><td colSpan={5} className="px-3 py-8 text-center text-xs text-[#71717a]">NO LIVE REPORTS YET — JOIN A ROOM, THEN RUN A SYNC BURST.</td></tr>}</tbody></table></div>
  </>;
}
function PeerTable({ peers, peerId, ownOffset, ownUncertainty }: { peers: Peer[]; peerId: string | null; ownOffset: number; ownUncertainty: number }) {
  return <EnhancedPeerTable peers={peers} peerId={peerId} ownOffset={ownOffset} ownUncertainty={ownUncertainty} />;
  const publicComparisonInput = useMemo(() => ({ limit: 3 }), []);
  const publicComparison = trpc.chronomesh.publicStabilityLeaderboard.useQuery(publicComparisonInput, { staleTime: 30_000, refetchInterval: 30_000 });
  const topSetups = useMemo(() => getTopComparisonSetups(publicComparison.data ?? [], 3), [publicComparison.data]);
  const [trace, setTrace] = useState<Array<Record<string, number>>>([]);
  const [visibleSeries, setVisibleSeries] = useState<Record<string, boolean>>({});
  const availableSeries = useMemo(() => ["localOffsetMs", ...topSetups.map((_, index) => `leader_${index}`)], [topSetups]);
  useEffect(() => { setVisibleSeries(current => reconcileSeriesVisibility(current, availableSeries)); }, [availableSeries]);
  useEffect(() => {
    if (!Number.isFinite(ownOffset) || topSetups.length === 0) return;
    setTrace(current => [...current.slice(-59), buildPeerComparisonPoint(Date.now(), ownOffset, topSetups)]);
  }, [ownOffset, topSetups]);
  const seriesControls = [{ key: "localOffsetMs", label: "YOU / LIVE ROOM REPORT", color: "#a3e635" }, ...topSetups.map((setup, index) => ({ key: `leader_${index}`, label: setup.setupLabel, color: ["#38bdf8", "#fbbf24", "#f472b6"][index] }))];
  return <><div className="mt-4 border border-[#a3e635]/15 bg-black/20 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><div className="numeric text-[10px] tracking-widest text-[#a3e635]">LIVE OFFSET / CONSENTED PUBLIC LEADERS</div><span className="numeric text-[9px] text-[#71717a]">YOUR LIVE OFFSET VS TOP {topSetups.length} PUBLIC AGGREGATES</span></div><p className="mt-1 text-[10px] leading-relaxed text-[#71717a]">The green trace is your room report. Use the series controls to simplify the view; comparison traces use only opted-in public setup aggregates.</p><div className="mt-3 flex flex-wrap gap-2" role="group" aria-label="Comparison chart series visibility">{seriesControls.map(series => <button key={series.key} type="button" aria-pressed={visibleSeries[series.key] !== false} onClick={() => setVisibleSeries(current => ({ ...current, [series.key]: current[series.key] === false }))} className={`numeric inline-flex items-center gap-1.5 border px-2 py-1 text-[9px] transition-colors ${visibleSeries[series.key] !== false ? "border-[#a3e635]/45 bg-[#a3e635]/10 text-[#e4e4e7]" : "border-[#52525b] bg-black/20 text-[#71717a]"}`}><span aria-hidden="true" className="h-2 w-2 rounded-full" style={{ backgroundColor: visibleSeries[series.key] !== false ? series.color : "#52525b" }} />{visibleSeries[series.key] !== false ? "HIDE" : "SHOW"} {series.label}</button>)}</div><div className="mt-3 h-[190px]">{trace.length && topSetups.length ? <ResponsiveContainer width="100%" height="100%"><LineChart data={trace}><CartesianGrid stroke="rgba(163,230,53,.10)" strokeDasharray="2 4" vertical={false} /><XAxis dataKey="timestamp" tickFormatter={value => new Date(value).toLocaleTimeString([], { minute: "2-digit", second: "2-digit" })} tick={{ fill: "#71717a", fontSize: 9 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "#71717a", fontSize: 9 }} axisLine={false} tickLine={false} width={44} /><Tooltip formatter={(value: number) => `${formatNumber(value)} ms`} labelFormatter={value => new Date(Number(value)).toLocaleTimeString()} contentStyle={{ background: "#111210", border: "1px solid rgba(163,230,53,.35)", fontFamily: "monospace", fontSize: 11 }} />{visibleSeries.localOffsetMs !== false && <Line type="monotone" dataKey="localOffsetMs" name="you / live room report" stroke="#a3e635" strokeWidth={2} dot={false} />}{topSetups.map((setup, index) => visibleSeries[`leader_${index}`] !== false && <Line key={setup.setupLabel} type="stepAfter" dataKey={`leader_${index}`} name={setup.setupLabel} stroke={["#38bdf8", "#fbbf24", "#f472b6"][index]} strokeWidth={1.5} dot={false} />)}</LineChart></ResponsiveContainer> : <div className="grid h-full place-items-center border border-dashed border-[#a3e635]/20"><span className="numeric text-[10px] text-[#71717a]">JOIN A ROOM, SYNC, AND WAIT FOR A CONSENTED PUBLIC LEADER TRACE.</span></div>}</div></div><div className="mt-4 overflow-x-auto border border-[#a3e635]/15"><table className="w-full min-w-[760px] numeric text-left text-[11px]"><thead className="bg-[#a3e635]/5 text-[9px] tracking-[.14em] text-[#a1a1aa]"><tr><th className="px-3 py-2">ANONYMOUS PEER / OPT-IN CONTEXT</th><th className="px-3 py-2">OFFSET → MESH</th><th className="px-3 py-2">RELATIVE → YOU</th><th className="px-3 py-2">JITTER</th><th className="px-3 py-2">CONFIDENCE</th></tr></thead><tbody>{peers.length ? peers.map(peer => { const confidence = deriveConfidence(peer.uncertaintyMs, peer.sampleCount); const relative = peer.offsetMs - ownOffset; const relativeUncertainty = Math.hypot(peer.uncertaintyMs, ownUncertainty); return <tr key={peer.id} className="border-t border-[#a3e635]/10"><td className="px-3 py-2 text-[#e4e4e7]"><div>{peer.id}{peer.id === peerId && <span className="ml-2 text-[#a3e635]">YOU</span>}</div>{peer.tags.length > 0 && <div className="mt-1 flex flex-wrap gap-1">{peer.tags.map(tag => <span key={tag} className="border border-[#a3e635]/25 bg-[#a3e635]/5 px-1 text-[9px] text-[#a3e635]">{tag}</span>)}</div>}{peer.description && <div className="mt-1 max-w-[250px] text-[9px] text-[#71717a]">{peer.description}</div>}</td><td className="px-3 py-2 text-[#a3e635]">{formatOffset(peer.offsetMs)} {formatUncertainty(peer.uncertaintyMs)}</td><td className="px-3 py-2 text-[#e4e4e7]">{formatOffset(relative)} {formatUncertainty(relativeUncertainty)}</td><td className="px-3 py-2 text-[#a1a1aa]">{formatNumber(peer.jitterMs)} ms {formatUncertainty(peer.jitterMs)}</td><td className="px-3 py-2"><span className={`border px-1.5 py-0.5 text-[9px] ${confidenceTone(confidence)}`}>{confidence.toUpperCase()}</span></td></tr>; }) : <tr><td colSpan={5} className="px-3 py-8 text-center text-xs text-[#71717a]">NO LIVE REPORTS YET — JOIN A ROOM, THEN RUN A SYNC BURST.</td></tr>}</tbody></table></div></>;
}
